/* Franky's Climate Hybrid v2 — clean photo materials + fully dynamic SVG controls.
 * Add this module AFTER frankys-climate-ui-card.js. No behavioral code is replaced.
 * Asset: /local/frankys-climate-hybrid-bg-v2.webp (see README).
 */
(() => {
  "use strict";
  const BASE_TAG = "frankys-climate-ui-card";
  const TAG = "frankys-climate-hybrid-card";
  const DEFAULT_BUTTONS = "data:image/webp;base64,";
  const DEFAULT_BACKGROUND = "data:image/webp;base64,";

  function install() {
    if (customElements.get(TAG)) return;
    const Base = customElements.get(BASE_TAG);
    if (!Base) return;

    class FrankysClimateHybridCard extends Base {
      static getStubConfig() {
        return { ...super.getStubConfig(), language: "de", name: "Klima" };
      }

      _hybridAngle(value) {
        const min = this._minTemp(), max = this._maxTemp();
        if (!(Number.isFinite(value) && max > min)) return -90;
        // Reference pointer is at twelve o'clock for the pictured 21 °C.
        // Two monotonic segments keep minimum and maximum on the lower dial ends.
        const pivot = Math.max(min, Math.min(max, 21));
        let degrees;
        if (value <= pivot && pivot > min) degrees = 135 + 135 * (value - min) / (pivot - min);
        else if (max > pivot) degrees = 270 + 135 * (value - pivot) / (max - pivot);
        else degrees = 270;
        return degrees - 360;
      }

      _sliderValue(event, slider, previousValue = NaN) {
        const matrix = slider.getScreenCTM();
        const svg = slider.ownerSVGElement;
        if (!matrix || !svg || !svg.createSVGPoint) return this._targetTemp();
        const screen = svg.createSVGPoint();
        screen.x = event.clientX; screen.y = event.clientY;
        const local = screen.matrixTransform(matrix.inverse());
        const x = local.x - 915, y = local.y - 528;
        let degrees = ((Math.atan2(y, x) * 180 / Math.PI) - 135 + 360) % 360;
        const min = this._minTemp(), max = this._maxTemp(), step = this._step();
        if (degrees > 270) degrees = Number.isFinite(previousValue)
          ? ((previousValue - min) / (max - min) >= .5 ? 270 : 0)
          : (degrees < 315 ? 270 : 0);
        // Convert from the dial's coordinate system into the same piecewise scale
        // as the image's pointer; preserve all native HA step/limit handling.
        const absoluteAngle = 135 + degrees;
        const pivot = Math.max(min, Math.min(max, 21));
        const native = absoluteAngle <= 270 && pivot > min
          ? min + (absoluteAngle - 135) / 135 * (pivot - min)
          : max > pivot ? pivot + (absoluteAngle - 270) / 135 * (max - pivot) : pivot;
        const stepped = min + Math.round((native - min) / step) * step;
        return Math.max(min, Math.min(max, Number(stepped.toFixed(8))));
      }

      _previewSlider(value) {
        if (!this._sliderDrag) return;
        this._sliderDrag.value = value;
        const label = this.shadowRoot.querySelector("[data-slider-value]");
        const marker = this.shadowRoot.querySelector("[data-slider-pointer]");
        if (label) label.textContent = this._fmtTemp(value);
        if (marker) marker.setAttribute("transform", `rotate(${(this._hybridAngle(value) + 90).toFixed(3)} 915 528)`);
      }

      _render() {
        if (!this._config || !this.shadowRoot || this._sliderDrag) return;
        const actual = this._actualTemp();
        const target = this._targetTemp();
        const mode = this._mode();
        const heaterOn = this._heaterOn();
        const isDe = this._lang() === "de";
        const bg = this._escape(this._config.background_image || DEFAULT_BACKGROUND);
        const buttonsImage = this._escape(this._config.button_sprite || DEFAULT_BUTTONS);
        const canMode = m => {
          const hvacModes = ((this._controlState() || {}).attributes || {}).hvac_modes || [];
          return !!this._config.mode_entity || this._hasModeAction(m) ||
            (Array.isArray(hvacModes) && hvacModes.includes({ AUS:"off", AUTO:"auto", MANUELL:"heat" }[m]));
        };
        const selected = mode === "AUS" ? 0 : mode === "AUTO" ? 1 : mode === "MANUELL" ? 2 : -1;
        const modeRegions = [
          {x:122,y:574,w:318,h:83,cy:616},
          {x:122,y:671,w:318,h:86,cy:715},
          {x:122,y:768,w:318,h:86,cy:813}
        ];
        const modeNames = ["AUS", "AUTO", "MANUELL"];
        const displayModeName = m => this._modeDisplay(m);
        // The original photographic curve is decorative; overlay real Recorder
        // samples when available so the existing 24h history remains usable.
        const history = Array.isArray(this._temperatureHistory) &&
          this._temperatureHistory.some(p => p && Number.isFinite(p.v)) &&
          typeof this._temperatureSparkline === "function"
            ? this._temperatureSparkline().replace(/#34e9ff/g, "#ff7e18")
            : "";
        const startAngle = this._hybridAngle(target) + 90;
        const status = this._error || (this._pending ? this._t("sending") : "");
        // Image retains original panel edges, steel, reflection, scale and button
        // textures at exact photographic positions. All changing regions (glass buttons, face, labels, flame and pointer) are independent SVG layers.
        this.shadowRoot.innerHTML = `
          <style>
            :host{display:block;max-width:100%;width:100%;margin:0 auto}
            .hybrid-frame{position:relative;width:100%;height:0;padding-bottom:62.615384615%;max-width:100%;overflow:hidden;user-select:none;-webkit-user-select:none;touch-action:manipulation}
            /* Geometry is exclusively defined by the shared SVG viewBox: no fixed CSS pixels. */
            svg{position:absolute;width:100%;height:100%;inset:0;display:block;overflow:hidden}
            .hit{pointer-events:all;cursor:pointer;fill:transparent}
            .hit:hover{fill:transparent}
            @media(prefers-reduced-motion:reduce){svg *{animation:none!important}}
          </style>
          <div class="hybrid-frame">
          <svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"
             viewBox="55 108 1300 814" preserveAspectRatio="xMidYMid meet"
             role="group" aria-label="${this._escape(this._config.name || "Klima")}">
            <defs>
              <filter id="hybridAmberGlow" x="-75%" y="-100%" width="250%" height="300%"><feGaussianBlur stdDeviation="7"/></filter>
              <filter id="hybridBlueGlow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="6"/></filter>
              <linearGradient id="hybridPointer" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stop-color="#ff4e03"/><stop offset="17%" stop-color="#ffa10b"/>
                <stop offset="49%" stop-color="#fff8be"/><stop offset="68%" stop-color="#ffe358"/><stop offset="100%" stop-color="#ed3e03"/>
              </linearGradient>
              <linearGradient id="hybridFlame" x1="0%" y1="100%" x2="0%" y2="0%">
                <stop offset="0%" stop-color="#fc3609"/><stop offset="47%" stop-color="#ff8e16"/><stop offset="100%" stop-color="#ffe36d"/>
              </linearGradient>
              <radialGradient id="dialMetal" cx="24%" cy="22%" r="91%">
                <stop offset="0%" stop-color="#455f72"/><stop offset="18%" stop-color="#19354a"/>
                <stop offset="40%" stop-color="#0c2131"/><stop offset="69%" stop-color="#061421"/>
                <stop offset="100%" stop-color="#020811"/>
              </radialGradient>
              <radialGradient id="dialTopGlare" cx="25%" cy="4%" r="77%">
                <stop offset="0%" stop-color="#b4d7ee" stop-opacity=".22"/>
                <stop offset="29%" stop-color="#aac2d9" stop-opacity=".07"/>
                <stop offset="100%" stop-color="#091522" stop-opacity="0"/>
              </radialGradient>
              <linearGradient id="modePanel" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stop-color="#082236"/><stop offset=".28" stop-color="#031725"/>
                <stop offset=".77" stop-color="#041524"/><stop offset="1" stop-color="#20130e"/>
              </linearGradient>
              <linearGradient id="modeInactive" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stop-color="#0d2838"/><stop offset=".32" stop-color="#071722"/>
                <stop offset="1" stop-color="#050d17"/>
              </linearGradient>
              <linearGradient id="modeActive" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stop-color="#085071"/><stop offset=".42" stop-color="#063046"/>
                <stop offset="1" stop-color="#071b30"/>
              </linearGradient>
              <linearGradient id="modeOffActive" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stop-color="#52351a"/><stop offset="1" stop-color="#190e0b"/>
              </linearGradient>
              <linearGradient id="plateHighlight" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stop-color="#bfefff" stop-opacity=".19"/>
                <stop offset=".45" stop-color="#83bad8" stop-opacity=".03"/>
                <stop offset="1" stop-color="#ff8623" stop-opacity=".08"/>
              </linearGradient>
              <pattern id="metalBrush" width="4" height="4" patternUnits="userSpaceOnUse">
                <path d="M0 1H4M0 3H4" stroke="#c6dfee" opacity=".065" stroke-width=".4"/>
              </pattern>
              <mask id="faceMaterialMask" x="686" y="306" width="459" height="479" maskUnits="userSpaceOnUse">
                <rect x="686" y="306" width="459" height="479" fill="#000"/>
                <circle cx="915" cy="528" r="216" fill="#fff"/>
                <!-- Keep the original photographic +/− glass buttons intact. -->
                <!-- The full clean dial covers all legacy text; button sprites follow. -->

              </mask>
              <linearGradient id="hybridCurrent" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stop-color="#f1fbff"/><stop offset="100%" stop-color="#b6e7ff"/>
              </linearGradient>
            </defs>
            <image x="55" y="108" width="1300" height="814" preserveAspectRatio="none" href="${bg}" xlink:href="${bg}"/>

            <!-- Fully redrawn face: no hidden photographic flame/label/number can remain.
                 A mask cuts around the preserved photo-realistic circular buttons. -->
            <g mask="url(#faceMaterialMask)" pointer-events="none">
              <circle cx="915" cy="528" r="216" fill="url(#dialMetal)"/>
              <circle cx="915" cy="528" r="215" fill="url(#metalBrush)"/>
              <circle cx="915" cy="528" r="215" fill="url(#dialTopGlare)"/>
              ${Array.from({length:45},(_,i)=>`<circle cx="915" cy="528" r="${80+i*3.0}" fill="none" stroke="#a8d4ec" stroke-width=".45" opacity=".025"/>`).join("")}
              <path d="M739 464Q779 360 917 330" fill="none" stroke="#c5e8f5" opacity=".095" stroke-width="17"/>
              <path d="M724 541Q734 429 797 383" fill="none" stroke="#b6ddfa" opacity=".075" stroke-width="6"/>
              <path d="M785 671Q915 769 1061 669" fill="none" stroke="#ff8e26" opacity=".07" stroke-width="7"/>
            </g>
            <image x="690" y="648" width="435" height="201" preserveAspectRatio="none"
               href="${buttonsImage}"/>

            <!-- The full mode-button surface is reconstructed once, before drawing
                 all three current-state buttons. Nothing inactive/active is baked in. -->
            <rect x="87" y="466" width="387" height="418" rx="21" fill="url(#modePanel)"/>
            <rect x="88" y="467" width="385" height="416" rx="20" fill="url(#plateHighlight)" stroke="#65cef3" stroke-opacity=".18" stroke-width="1.5"/>
            <path d="M88 540V858Q88 883 113 883H440" fill="none" stroke="#ffa14c" opacity=".22" stroke-width="2.5"/>
            <path d="M473 824V857Q473 883 449 883" fill="none" stroke="#ff7423" opacity=".6" stroke-width="2.4"/>
            <g transform="translate(153 519)" fill="none" stroke="#14dfff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
              <circle r="25" opacity=".65" filter="url(#hybridBlueGlow)"/>
              <circle r="23"/><circle r="10"/>
              ${Array.from({length:8},(_,i)=>`<path d="M-7 -30 V-24 H7 V-30" transform="rotate(${i*45})"/>`).join("")}
            </g>
            <text x="214" y="532" font-size="32" font-weight="500" fill="#e1f4ff" font-family="Arial,Helvetica,sans-serif">${this._t("mode")}</text>
            ${modeRegions.map((r,i)=>{
              const name=modeNames[i], enabled=canMode(name), active=selected===i && enabled;
              const orange=selected===0 && i===0;
              const stroke=active?(orange?"#ff8d33":"#1ddfff"):(enabled?"#3f9cbc":"#385061");
              const fill=active?(orange?"url(#modeOffActive)":"url(#modeActive)"):"url(#modeInactive)";
              const iconColor=active?(orange?"#ffae70":"#18eaff"):(enabled?"#d1e5f0":"#738c9b");
              const textColor=active?(orange?"#ffb985":"#1de6ff"):(enabled?"#d5e9f5":"#8299a6");
              return `<g>
                ${active?`<rect x="${r.x-3}" y="${r.y-3}" width="${r.w+6}" height="${r.h+6}" rx="22" fill="none" stroke="${stroke}" stroke-width="9" opacity=".58" filter="url(#hybridBlueGlow)"/>`:""}
                <rect x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="21" fill="${fill}" stroke="${stroke}" stroke-width="${active?3.5:1.6}"/>
                <path d="M${r.x+17} ${r.y+2} H${r.x+r.w-22}" stroke="#e1faff" stroke-width="1.4" opacity="${active?.54:.22}"/>
                <path d="M${r.x+30} ${r.y+r.h-3} H${r.x+r.w-24}" stroke="${stroke}" stroke-width="1.5" opacity="${active?.6:.18}"/>
                <g transform="translate(190 ${r.cy})" stroke="${iconColor}" stroke-width="3.2" fill="none" opacity="${enabled?1:.45}">
                  <circle r="7"/><path d="M0-9C-21-24-29-7-13-1M9 0C24-21 7-29 1-13M0 9C21 24 29 7 13 1M-9 0C-24 21-7 29-1 13"/>
                </g>
                <text x="310" y="${r.cy+10}" text-anchor="middle" fill="${textColor}" font-size="${name==="MANUELL"?30:32}" font-family="Arial,Helvetica,sans-serif" font-weight="${active?650:550}">${displayModeName(name)}</text>
                ${enabled?`<rect class="hit" data-action="mode" data-mode="${name}" x="${r.x}" y="${r.y}" width="${r.w}" height="${r.h}" rx="21"/>`:""}
              </g>`;
            }).join("")}


            <!-- Current temperature and unit: native HA reading, no baked-in text. -->
            <text x="281" y="356" text-anchor="middle" font-family="Arial,Helvetica,sans-serif"
               font-size="99" font-weight="600" fill="url(#hybridCurrent)" letter-spacing="-3">${this._fmtTemp(actual)}</text>
            <text x="391" y="320" font-family="Arial,Helvetica,sans-serif" font-size="38" font-weight="550" fill="#e5f8ff">${this._displayTempUnit()}</text>

            <!-- Real 24h recorder series; reference orange wave remains a decorative accent. -->
            <!-- The original decorative orange curve is preserved. Live recorder data
                 remains available through the existing base card implementation. -->

            <!-- Source state controls the flame. The whole inner dial is an independent brushed-metal SVG surface. -->
            ${heaterOn ? `<g fill="url(#hybridFlame)" transform="translate(0 0)">
                <path d="M876 501Q899 486 886 459Q875 438 890 412Q882 439 901 458Q913 479 876 501Z" opacity=".56" filter="url(#hybridAmberGlow)"/>
                <path d="M907 500Q928 482 918 455Q911 433 924 412Q919 438 933 457Q942 478 907 500Z" opacity=".7" filter="url(#hybridAmberGlow)"/>
                <path d="M938 501Q963 483 947 453Q941 430 956 413Q950 444 966 459Q972 480 938 501Z" opacity=".55" filter="url(#hybridAmberGlow)"/>
                <path d="M876 501Q899 486 886 459Q875 438 890 412Q882 439 901 458Q913 479 876 501Z"/>
                <path d="M907 500Q928 482 918 455Q911 433 924 412Q919 438 933 457Q942 478 907 500Z"/>
                <path d="M938 501Q963 483 947 453Q941 430 956 413Q950 444 966 459Q972 480 938 501Z"/>
              </g>` : ""}
            ${this._config.flame_switch_entity && mode !== "AUS" ? '<rect class="hit" fill="transparent" data-action="flame" x="855" y="401" width="125" height="110"/>' : ""}

            <text x="916" y="566" text-anchor="middle" fill="#e7f4fe" font-family="Arial,Helvetica,sans-serif"
               font-size="32" font-weight="500">${this._t("target")}</text>
            <text data-slider-value x="900" y="647" text-anchor="middle" font-family="Arial,Helvetica,sans-serif"
               font-size="110" font-weight="700" fill="#ffa12e" letter-spacing="-4"
               style="filter:drop-shadow(0 0 8px rgba(255,108,10,.64))">${this._fmtTemp(target)}</text>
            <text x="1013" y="602" font-family="Arial,Helvetica,sans-serif" font-size="36" font-weight="600" fill="#ffb55c">${this._displayTempUnit()}</text>

            <!-- Real moveable pointer, referenced to the dial centre. -->
            <g data-slider-pointer transform="rotate(${startAngle.toFixed(3)} 915 528)" pointer-events="none">
              <rect x="889" y="251" width="55" height="131" rx="27" fill="#f56b06" opacity=".65" filter="url(#hybridAmberGlow)"/>
              <rect x="893" y="253" width="44" height="122" rx="22" fill="#130a09" stroke="#f86910" stroke-width="3"/>
              <rect x="897" y="257" width="35" height="111" rx="18" fill="url(#hybridPointer)" stroke="#ff8309" stroke-width="3"/>
              <rect x="903" y="261" width="19" height="96" rx="10" fill="#fff6b3" opacity=".67"/>
              <path d="M901 274V351" stroke="#ffffe5" stroke-opacity=".52" stroke-width="3" stroke-linecap="round"/>
            </g>
            <!-- Invisible arc hit-area feeds the existing touch/drag/safety logic. -->
            <path data-slider d="M695.8 747.2 A310 310 0 1 1 1134.2 747.2"
               stroke="transparent" fill="none" stroke-width="58"
               style="pointer-events:stroke;touch-action:none;cursor:pointer"/>

            <!-- Actual circles belong to the background photograph; hit layers remain independent. -->
            <circle class="hit" fill="transparent" data-action="minus" cx="792" cy="748" r="76"/>
            <circle class="hit" fill="transparent" data-action="plus" cx="1027" cy="748" r="76"/>
            ${this._scheduleEnabled() ? `<g data-action="schedule" role="button" tabindex="0" aria-label="${this._t("schedule")}" style="cursor:pointer">
              <circle cx="1270" cy="184" r="22" fill="#071626" stroke="#34daff" stroke-width="2"/>
              <path d="M1270 170V185L1281 191" fill="none" stroke="#4deaff" stroke-width="3" stroke-linecap="round"/>
              <circle class="hit" fill="transparent" cx="1270" cy="184" r="24"/></g>` : ""}
            ${status ? `<rect x="733" y="841" width="363" height="35" rx="15" fill="#061b2a" fill-opacity=".91" stroke="#ff9c3a"/>
              <text x="914" y="865" text-anchor="middle" font-size="19" fill="#ffcf8d">${this._escape(status)}</text>` : ""}
          </svg></div>`;

        this._bindSlider();
        const schedule = this.shadowRoot.querySelector('[data-action="schedule"]');
        if (schedule) schedule.addEventListener("keydown", event => {
          if (event.key === "Enter" || event.key === " ") { event.preventDefault(); this._openSchedule(); }
        });
        this.shadowRoot.querySelectorAll("[data-action]").forEach(element => {
          element.addEventListener("click", async event => {
            const action = event.currentTarget.dataset.action;
            if (action === "mode") await this._setMode(event.currentTarget.dataset.mode);
            if (action === "flame") await this._toggleFlame();
            if (action === "minus") await this._changeTarget(-this._step());
            if (action === "plus") await this._changeTarget(this._step());
            if (action === "schedule") this._openSchedule();
          });
        });
      }
    }
    customElements.define(TAG, FrankysClimateHybridCard);
    window.customCards = window.customCards || [];
    if (!window.customCards.some(card => card.type === TAG)) {
      window.customCards.push({
        type: TAG,
        name: "Franky's Climate Hybrid (Originaldesign)",
        description: "Originaler 3D-Neon-Look mit Home Assistant Climate UI-Steuerung",
        preview: false
      });
    }
  }
  customElements.whenDefined(BASE_TAG).then(install);
})();